// Contract check: every API call the frontend makes (path + method) must exist in the backend's
// OpenAPI document (openapi.json, regenerated by `python -m app.openapi_export`).
// Usage: node scripts/api-contract-check.mjs
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const ROOT = new URL("../", import.meta.url).pathname;
const spec = JSON.parse(readFileSync(join(ROOT, "openapi.json"), "utf8"));
const norm = (p) => p.replace(/\{[^}]+\}/g, "{}").replace(/\/$/, "");
const known = new Map();
for (const [p, ops] of Object.entries(spec.paths)) known.set(norm(p), new Set(Object.keys(ops).map((m) => m.toUpperCase())));

const files = [];
(function walk(d) { for (const f of readdirSync(d)) { const p = join(d, f); if (statSync(p).isDirectory()) walk(p); else if (/\.tsx?$/.test(f) && !p.includes("/i18n/")) files.push(p); } })(join(ROOT, "src"));

const calls = [];
const CALL = /\b(?:api|apiPage)\s*(?:<[^()]*?>)?\(\s*(["`])([^"`]+)\1/g;
const HREF = /(?:href|src)=\{?\s*(["`])(\/api\/v1\/[^"`]+)\1/g;
for (const f of files) {
  const s = readFileSync(f, "utf8");
  for (const m of s.matchAll(CALL)) {
    // options follow the URL: `{ method: "POST", json: {...} }` — look ahead only until the call closes
    const rest = s.slice(m.index + m[0].length, m.index + m[0].length + 600);
    const opts = rest.startsWith(",") ? rest.slice(0, rest.search(/\)\s*[;.)\n]/) + 1 || 600) : "";
    const method = (/method:\s*"(\w+)"/.exec(opts) || [, "GET"])[1].toUpperCase();
    calls.push({ f, raw: m[2], path: "/api/v1" + m[2], method });
  }
  for (const m of s.matchAll(HREF)) calls.push({ f, raw: m[2], path: m[2], method: "GET" });
}
const missing = [];
for (const c of calls) {
  const p = norm(c.path.replace(/\$\{[^}]+\}/g, "{}").split("?")[0]);
  // a `${x}` segment in the call may stand for a literal segment of the API (e.g. documents/${kind})
  const re = new RegExp("^" + p.split("/").map((seg) => (seg === "{}" ? "[^/]+" : seg.replace(/[.*+?^$()|[\]\\]/g, "\\$&"))).join("/") + "$");
  const ok = known.get(p)?.has(c.method)
    || [...known].some(([k, ms]) => ms.has(c.method) && re.test(k))
    || [...known.keys()].some((k) => k.endsWith("{}") && k.includes("/files/") && p.startsWith(k.slice(0, -2)));
  if (!ok) missing.push(`${c.method} ${c.raw}  (${c.f.replace(ROOT, "")})`);
}
console.log(`api calls=${calls.length} openapi paths=${known.size} missing=${missing.length}`);
for (const m of missing) console.log("  MISSING " + m);
process.exit(missing.length ? 1 : 0);
